select 
from trade_agent_profile


        and agent_code = #{agentCode}


        and agent_name like concat('%', #{agentName}, '%')


        and agent_type = #{agentType}


        and enabled = #{enabled}


        and llm_enabled = #{llmEnabled}


        and dialogue_enabled = #{dialogueEnabled}


